/*
 * A191121  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then 3x-1 and 4x-1 are in a.
 * https://oeis.org/A191121
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 20, u16 n <= 947, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A191121:
   Generated by the closure of 1 under the operations
   x → 3x - 1 and x → 4x - 1, then sorted increasingly.
   The algorithm uses a min‑heap to produce the numbers in order
   while keeping track of the last output to skip duplicates. */

#include <stdlib.h>
#include <stdbool.h>

/* Push a value into a min‑heap. */
static void heap_push(seq_t **arr, size_t *len, size_t *cap, seq_t val)
{
    if (*len >= *cap) {
        *cap = (*cap == 0) ? 64 : (*cap << 1);
        *arr = (seq_t *)realloc(*arr, *cap * sizeof(seq_t));
    }
    size_t i = *len;
    (*arr)[i] = val;
    ++*len;
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if ((*arr)[i] < (*arr)[p]) {
            seq_t tmp = (*arr)[i];
            (*arr)[i] = (*arr)[p];
            (*arr)[p] = tmp;
            i = p;
        } else break;
    }
}

/* Pop the smallest value from a min‑heap. */
static seq_t heap_pop(seq_t **arr, size_t *len)
{
    seq_t root = (*arr)[0];
    --*len;
    if (*len > 0) {
        (*arr)[0] = (*arr)[*len];
        size_t i = 0;
        while (1) {
            size_t l = (i << 1) + 1;
            size_t r = l + 1;
            if (l >= *len) break;
            size_t m = l;
            if (r < *len && (*arr)[r] < (*arr)[l]) m = r;
            if ((*arr)[m] < (*arr)[i]) {
                seq_t tmp = (*arr)[i];
                (*arr)[i] = (*arr)[m];
                (*arr)[m] = tmp;
                i = m;
            } else break;
        }
    }
    return root;
}

seq_t a(idx_t n)
{
    /* Static state to allow arbitrary call order and caching. */
    static seq_t *seq = NULL, *heap = NULL;
    static size_t seq_len = 0, seq_cap = 0;
    static size_t heap_len = 0, heap_cap = 0;
    static bool prev_set = false;
    static seq_t prev_val = 0;

    /* Initialization on first call. */
    if (seq == NULL) {
        seq_cap = 64;
        seq = (seq_t *)malloc(seq_cap * sizeof(seq_t));
        seq[0] = (seq_t)1;
        seq_len = 1;

        heap_cap = 64;
        heap = (seq_t *)malloc(heap_cap * sizeof(seq_t));
        heap_len = 0;

        /* Insert initial children: 3*1-1 = 2, 4*1-1 = 3. */
        seq_t c1 = (seq_t)3 * seq[0] - (seq_t)1;
        seq_t c2 = (seq_t)4 * seq[0] - (seq_t)1;
        heap_push(&heap, &heap_len, &heap_cap, c1);
        heap_push(&heap, &heap_len, &heap_cap, c2);
    }

    /* Generate terms up to the requested index. */
    while (seq_len < (size_t)n) {
        seq_t x = heap_pop(&heap, &heap_len);

        /* Skip duplicates. */
        if (prev_set && x == prev_val)
            continue;

        /* Accept a new term. */
        if (seq_len >= seq_cap) {
            seq_cap <<= 1;
            seq = (seq_t *)realloc(seq, seq_cap * sizeof(seq_t));
        }
        seq[seq_len++] = x;
        prev_val = x;
        prev_set = true;

        /* Generate its children. */
        seq_t child1 = (seq_t)3 * x - (seq_t)1;
        seq_t child2 = (seq_t)4 * x - (seq_t)1;
        heap_push(&heap, &heap_len, &heap_cap, child1);
        heap_push(&heap, &heap_len, &heap_cap, child2);
    }

    return seq[n - 1];
}
